//!
//! Test binaries in this workspace re-invoke themselves under helper names such
//! as `codex-linux-sandbox` or `apply_patch` (via the arg0 trick). To make that
//! work, and to keep those helper aliases hermetic, the test harness needs to
//! run some setup from a `#[ctor]` static initializer before any test threads
//! start.
//!
//! This crate centralizes that logic so individual test crates don't each
//! re-implement the same environment juggling.

use std::path::Path;

use codex_arg0::Arg0DispatchPaths;
use codex_arg0::Arg0PathEntryGuard;
use tempfile::TempDir;

/// Guard returned by [`configure_test_binary_dispatch`] when arg0 aliases are
/// installed for a test binary.
///
/// Holds the temporary `CODEX_HOME` directory used to house the alias symlinks
/// as well as the underlying [`Arg0PathEntryGuard`] that keeps the per-session
/// PATH entry alive and locked. Dropping this guard tears both down, so tests
/// should keep it alive for the lifetime of the process (e.g. by storing it in
/// a `static`).
pub struct TestBinaryDispatchGuard {
    /// Temporary directory used as `CODEX_HOME` while installing aliases. Kept
    /// alive so the alias symlinks it contains remain valid.
    _codex_home: TempDir,
    /// Keeps the arg0 PATH entry alive and exposes the resolved helper paths.
    path_entry: Arg0PathEntryGuard,
}

impl TestBinaryDispatchGuard {
    /// Returns the helper executable paths derived while installing the arg0
    /// aliases (e.g. the `codex-linux-sandbox` alias path on Linux).
    pub fn paths(&self) -> &Arg0DispatchPaths {
        self.path_entry.paths()
    }
}

/// Controls what [`configure_test_binary_dispatch`] does for the current process
/// invocation. Returned by the `classify` closure based on how the test binary
/// was invoked (its executable name and first argument).
pub enum TestBinaryDispatchMode {
    /// Dispatch via arg0 (running any helper the process was invoked as, which
    /// never returns) and otherwise return `None` without installing aliases.
    DispatchArg0Only,
    /// Do nothing and return `None`.
    Skip,
    /// Set up a temporary `CODEX_HOME`, install the arg0 dispatch aliases into
    /// it, restore the previous `CODEX_HOME`, and return the resulting guard.
    InstallAliases,
}

/// Reads the current process's `argv0`/`argv1`, asks `classify` how to handle
/// this invocation, and acts accordingly.
///
/// `codex_home_prefix` is used as the filename prefix for the temporary
/// `CODEX_HOME` directory created in [`TestBinaryDispatchMode::InstallAliases`]
/// mode.
///
/// `classify` receives the executable's file name (the basename of `argv0`) and
/// the optional first argument (`argv1`), and returns the desired
/// [`TestBinaryDispatchMode`].
///
/// Intended to be called from a `#[ctor]` static initializer, before any test
/// threads are spawned, because it may mutate process-global state (the `PATH`
/// and `CODEX_HOME` environment variables).
pub fn configure_test_binary_dispatch<F>(
    codex_home_prefix: &str,
    classify: F,
) -> Option<TestBinaryDispatchGuard>
where
    F: FnOnce(&str, Option<&str>) -> TestBinaryDispatchMode,
{
    let mut args = std::env::args_os();
    let argv0 = args.next().unwrap_or_default();
    let argv1 = args.next();

    let exe_name = Path::new(&argv0)
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("");
    let argv1 = argv1.as_ref().and_then(|arg| arg.to_str());

